def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_opp = history[-1]

    # Calculate recent statistics to identify opponent type
    window = min(10, n)
    recent_history = history[-window:]
    opp_c_recent = sum(1 for _, b in recent_history if b == 'C')
    my_c_recent = sum(1 for a, _ in recent_history if a == 'C')

    overall_opp_c = sum(1 for _, b in history if b == 'C')
    overall_my_c = sum(1 for a, _ in history if a == 'C')

    recent_opp_rate = opp_c_recent / window
    overall_opp_rate = overall_opp_c / n

    # Streaks
    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_streak += 1
        else:
            break

    rounds_left = 100 - n

    # Endgame exploitation logic (last 3 rounds)
    if rounds_left <= 2:
        if last_opp == 'C':
            return 'D'
        if def_streak >= 2:
            return 'D'
        return 'C'

    if rounds_left <= 5:
        if recent_opp_rate >= 0.8 and def_streak == 0:
             return 'C' # Maintain high score with cooperative bots
        if last_opp == 'C':
            return 'D' # Try to exploit once more if they are forgiving
        return 'D' if def_streak > 0 else 'C'

    # Primary Strategy Logic

    # 1. If we are currently being punished by a TFT-like bot or mutual defection spiral
    if last_opp == 'D':
        # If the opponent has been mostly cooperative recently, it might be a single defection or noise
        if recent_opp_rate >= 0.7:
            # Tit-for-Tat response: Defect once, then cooperate next turn if they do
            return 'D'

        # If opponent is generally defecting, stay defensive
        if overall_opp_rate < 0.4:
            return 'D'

        # Moderate/High cooperation but recent defection: Probabilistic forgiveness to escape traps
        # More likely to forgive if the streak is short and overall behavior is good
        prob_coop = 0.3 + 0.2 * (recent_opp_rate - 0.5)
        if def_streak == 1 and rng.random() < prob_coop:
            return 'C'

        return 'D'

    # 2. Opponent Cooperated Last Round
    else:
        # Check if we should exploit a highly cooperative pattern
        # If opponent is very consistent C (>90% recent), defect with low probability to test/react
        if recent_opp_rate >= 0.9:
            if rng.random() < 0.05:
                return 'D'
            return 'C'

        # Standard Reciprocal Cooperation
        # If we have been cooperating well, keep going
        if my_c_recent == window:
            return 'C'

        # If we defected recently but they still cooperated, reciprocate with cooperation
        if my_c_recent < window:
            return 'C'

        return 'C'
